<style>
.best-sellers-outer { width: 100%; padding: 40px 5%; background-color: #ffffff; box-sizing: border-box; font-family: 'Arial', sans-serif; }
.best-sellers-inner { margin: 0 auto; width: 100%; }
.bs-header { display: flex; justify-content: space-between; align-items: baseline; border-bottom: 1px solid #e5e5e5; padding-bottom: 15px; margin-bottom: 25px; }
.bs-title { font-size: 22px; font-weight: 800; text-transform: uppercase; color: #111111; margin: 0; }
.bs-title span { color: #E2211C; }
.bs-link { color: #E2211C; text-decoration: none; font-weight: bold; font-size: 13px; text-transform: uppercase; }
.bs-link:hover { text-decoration: underline; }
.bs-carousel-wrapper { position: relative; display: flex; align-items: center; }
.bs-track { display: flex; gap: 15px; overflow-x: auto; scroll-behavior: smooth; padding: 5px 0; -ms-overflow-style: none; scrollbar-width: none; }
.bs-track::-webkit-scrollbar { display: none; }
.bs-card { display: flex; align-items: center; flex: 0 0 280px; padding: 15px; border: 1px solid #e5e5e5; border-radius: 4px; background-color: #ffffff; box-sizing: border-box; text-decoration: none; transition: box-shadow 0.3s ease, border-color 0.3s ease; }
.bs-card:hover { border-color: #cccccc; box-shadow: 0 4px 10px rgba(0,0,0,0.05); }
.bs-img-container { width: 70px; height: 70px; flex-shrink: 0; margin-right: 15px; display: flex; align-items: center; justify-content: center; }
.bs-img-container img { max-width: 100%; max-height: 100%; object-fit: contain; }
.bs-info { flex: 1; display: flex; flex-direction: column; align-items: center; text-align: center; }
.bs-name { font-size: 12px; font-weight: bold; color: #111111; margin: 0 0 8px 0; line-height: 1.3; }
.bs-rating { margin-bottom: 12px; }
.bs-rating .icon--ratingEmpty svg { stroke: #E2211C; fill: none; width: 12px; height: 12px; }
.bs-rating .icon--ratingFull svg { fill: #E2211C; width: 12px; height: 12px; }
.bs-price { font-size: 13px; font-weight: 900; color: #111111; margin: 0; }
.bs-arrow { position: absolute; top: 50%; transform: translateY(-50%); width: 40px; height: 40px; background-color: #ffffff; border: 1px solid #e5e5e5; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; z-index: 10; box-shadow: 0 2px 5px rgba(0,0,0,0.1); color: #111111; font-weight: bold; font-size: 18px; transition: background-color 0.2s, color 0.2s; }
.bs-arrow:hover { background-color: #E2211C; color: #ffffff; border-color: #E2211C; }
.bs-arrow.left { left: -20px; }
.bs-arrow.right { right: -20px; }
@media (max-width: 1024px) { .bs-arrow.left { left: 0px; } .bs-arrow.right { right: 0px; } }
@media (max-width: 768px) { .best-sellers-outer { padding: 40px 20px; } .bs-header { flex-direction: column; align-items: flex-start; gap: 10px; } .bs-arrow { display: none; } .bs-card { flex: 0 0 260px; } }
</style>

<div class="best-sellers-outer">
    <div class="best-sellers-inner">
        
        <div class="bs-header">
            <h2 class="bs-title">Our <span>Best Sellers</span></h2>
            <a href="/categories" class="bs-link">View All Best Sellers &rarr;</a>
        </div>

        <div class="bs-carousel-wrapper" id="bsCarousel">
            <button class="bs-arrow left" id="bsLeftArrow">&lt;</button>
            <div class="bs-track" id="bsTrack">
                
                <!-- PULLING REAL TOP SELLERS -->
                {{#each products.top_sellers}}
                    <a href="{{url}}" class="bs-card">
                        <div class="bs-img-container">
                            <img src="{{getImage image 'productgallery_size' (cdn theme_settings.default_image_product)}}" alt="{{image.alt}}" title="{{image.alt}}">
                        </div>
