                                    {{> components/products/ratings rating=rating}}
                                </div>
                            {{/if}}
                            <p class="bs-price">
                                {{#if price.with_tax}}{{price.with_tax.formatted}}{{/if}}
                                {{#if price.without_tax}}{{price.without_tax.formatted}}{{/if}}
                            </p>
                        </div>
                    </a>
                {{/each}}
                
            </div>
            <button class="bs-arrow right" id="bsRightArrow">&gt;</button>
        </div>
    </div>
</div>

<script>
document.addEventListener('DOMContentLoaded', function() {
    const track = document.getElementById('bsTrack');
    const leftArrow = document.getElementById('bsLeftArrow');
    const rightArrow = document.getElementById('bsRightArrow');
    const carouselWrapper = document.getElementById('bsCarousel');
    if (!track) return;

    const scrollAmount = 295; 
    let autoScrollInterval;

    function scrollRight() {
        if (track.scrollLeft + track.clientWidth >= track.scrollWidth - 10) { track.scrollTo({ left: 0, behavior: 'smooth' }); } 
        else { track.scrollBy({ left: scrollAmount, behavior: 'smooth' }); }
    }
    function scrollLeft() {
        if (track.scrollLeft <= 0) { track.scrollTo({ left: track.scrollWidth, behavior: 'smooth' }); } 
        else { track.scrollBy({ left: -scrollAmount, behavior: 'smooth' }); }
    }

    if(rightArrow) rightArrow.addEventListener('click', scrollRight);
    if(leftArrow) leftArrow.addEventListener('click', scrollLeft);

    function startAutoScroll() { autoScrollInterval = setInterval(scrollRight, 3500); }
    function stopAutoScroll() { clearInterval(autoScrollInterval); }

    carouselWrapper.addEventListener('mouseenter', stopAutoScroll);
    carouselWrapper.addEventListener('mouseleave', startAutoScroll);
    carouselWrapper.addEventListener('touchstart', stopAutoScroll);
    carouselWrapper.addEventListener('touchend', startAutoScroll);

    startAutoScroll();
});
</script>
